import http from 'k6/http';
import { sleep, check } from 'k6';
import exec from 'k6/execution';
import { Rate, Counter } from 'k6/metrics';

const BASE = __ENV.BASE_URL || 'http://127.0.0.1:8000';
const PASSWORD = 'bench';
const VUS = 2;
const TOTAL_ARRIVALS = 275;

const businessFailure = new Rate('business_failure');
const workSuccess = new Counter('work_success');

export const options = {
  scenarios: {
    work: {
      executor: 'per-vu-iterations',
      vus: VUS,
      iterations: 1,
      maxDuration: '60s',
      gracefulStop: '5s',
    },
  },
};

export function setup() {
  return { startAt: Date.now() + 6000 };
}

export default function (data) {
  const vuIdx = (exec.vu.idInTest - 1) % VUS;
  const username = `bench-${vuIdx + 1}`;
  const auth = loginWithRetry(username, 5);
  if (!auth) {
    sleep(35);
    return;
  }

  const state = { csrf: auth.csrf, lastRawAt: 0 };
  const startAt = data.startAt;

  for (let n = vuIdx; n < TOTAL_ARRIVALS; n += VUS) {
    const due = startAt + sequenceTime(n) * 1000;
    waitUntil(due);
    sendWorkWithRecovery(state, startAt, username);
  }
}

function sequenceTime(n) {
  if (n < 0) return 0;
  if (n < 25) return n / 5;
  if (n < 75) {
    return 5 + (n - 25) * ((14.4 - 5) / (74 - 25));
  }
  if (n < 225) return 15 + (n - 75) / 15;
  if (n < 275) return 25 + (n - 225) / 5;
  return Infinity;
}

function waitUntil(ms) {
  const delay = ms - Date.now();
  if (delay > 0) sleep(delay / 1000);
}

function sendWorkWithRecovery(state, startAt, username) {
  let retries429 = 0;
  let recoveries = 0;

  while (true) {
    enforceMinRawInterval(state, startAt);
    state.lastRawAt = Date.now();

    const res = http.post(BASE + '/v2/work', '{}', {
      headers: {
        'Content-Type': 'application/json',
        'X-CSRF-Token': state.csrf,
      },
      redirects: 0,
      tags: { name: 'work' },
    });

    const status = res.status;
    const body = safeJson(res);
    const error = body && body.error;

    if (status === 429) {
      businessFailure.add(false);
      retries429++;
      if (retries429 > 4) return;
      const retryAfter = parseRetryAfter(res);
      sleep(retryAfter);
      continue;
    }

    if (status === 401) {
      if (error === 'expired') {
        businessFailure.add(false);
        if (recoveries < 1) {
          recoveries++;
          const renewedCsrf = renewSession(state.csrf);
          if (renewedCsrf) {
            state.csrf = renewedCsrf;
            continue;
          }
          const fresh = login(username);
          if (fresh) {
            state.csrf = fresh.csrf;
            continue;
          }
        }
        return;
      }

      if (error === 'session') {
        businessFailure.add(false);
        if (recoveries < 1) {
          recoveries++;
          const fresh = login(username);
          if (fresh) {
            state.csrf = fresh.csrf;
            continue;
          }
        }
        return;
      }

      if (error === 'denied') {
        businessFailure.add(true);
        check(res, { 'denied is not expiry': () => false });
        return;
      }

      businessFailure.add(true);
      return;
    }

    if (status >= 400) {
      businessFailure.add(true);
      if (status >= 500) {
        check(res, { 'work no 5xx': () => false });
      }
      return;
    }

    if (status === 200 && body && body.ok === true) {
      businessFailure.add(false);
      workSuccess.add(1);
      check(res, { 'work ok': (r) => r.status === 200 });
      if (body.csrf) state.csrf = body.csrf;
      return;
    }

    businessFailure.add(true);
    return;
  }
}

function enforceMinRawInterval(state, startAt) {
  if (!state.lastRawAt) return;
  const now = Date.now();
  const interval = minRawIntervalMs(now, startAt);
  const elapsed = now - state.lastRawAt;
  if (elapsed < interval) {
    sleep((interval - elapsed) / 1000);
  }
}

function minRawIntervalMs(now, startAt) {
  const t = (now - startAt) / 1000;
  let rate;
  if (t < 15) rate = 5;
  else if (t < 25) rate = 15;
  else rate = 5;

  const burstLimit = Math.ceil(1.5 * rate) + 1;
  return (1000 * VUS) / burstLimit;
}

function parseRetryAfter(res) {
  const h = getHeader(res, 'Retry-After');
  if (!h) return 1;

  const seconds = parseFloat(h);
  if (!isNaN(seconds)) return Math.min(Math.max(seconds, 0), 5);

  const date = Date.parse(h);
  if (!isNaN(date)) {
    const sec = (date - Date.now()) / 1000;
    return Math.min(Math.max(sec, 0), 5);
  }

  return 1;
}

function renewSession(csrf) {
  const res = http.post(BASE + '/v2/session/renew', '{}', {
    headers: {
      'Content-Type': 'application/json',
      'X-CSRF-Token': csrf,
    },
    redirects: 0,
    tags: { name: 'renew' },
  });

  if (res.status >= 200 && res.status < 300) {
    const body = safeJson(res);
    if (body && body.csrf) return body.csrf;
    return csrf;
  }

  return null;
}

function loginWithRetry(username, attempts) {
  for (let i = 0; i < attempts; i++) {
    const auth = login(username);
    if (auth) return auth;
    sleep(0.5);
  }
  return null;
}

function login(username) {
  const formRes = http.get(BASE + '/v2/login-form', {
    redirects: 0,
    tags: { name: 'login-form' },
  });
  if (formRes.status !== 200) return null;

  const formCsrf = extractCsrf(formRes.body || '');
  if (!formCsrf) return null;

  const loginRes = http.post(
    BASE + '/v2/login',
    JSON.stringify({ username: username, password: PASSWORD, csrf: formCsrf }),
    {
      headers: { 'Content-Type': 'application/json' },
      redirects: 0,
      tags: { name: 'login' },
    }
  );

  let finalRes = loginRes;
  if (loginRes.status >= 300 && loginRes.status < 400) {
    const loc = getHeader(loginRes, 'Location');
    if (!loc) return null;
    finalRes = http.get(absoluteUrl(loc), {
      redirects: 0,
      tags: { name: 'login-redirect' },
    });
  }

  let csrf = '';
  const finalBody = safeJson(finalRes);
  if (finalBody && finalBody.csrf) csrf = finalBody.csrf;
  if (!csrf) csrf = extractCsrf(finalRes.body || '');
  if (!csrf) {
    const loginBody = safeJson(loginRes);
    if (loginBody && loginBody.csrf) csrf = loginBody.csrf;
  }
  if (!csrf) csrf = formCsrf;

  if (finalRes.status >= 200 && finalRes.status < 300 && csrf) {
    return { csrf: csrf };
  }

  return null;
}

function absoluteUrl(loc) {
  if (/^https?:\/\//i.test(loc)) return loc;
  if (loc.charAt(0) === '/') return BASE + loc;
  return BASE + '/' + loc;
}

function getHeader(res, name) {
  const target = name.toLowerCase();
  for (const key in res.headers) {
    if (key.toLowerCase() === target) {
      const value = res.headers[key];
      return Array.isArray(value) ? value[0] : value;
    }
  }
  return '';
}

function safeJson(res) {
  try {
    return res.json();
  } catch (e) {
    return null;
  }
}

function extractCsrf(html) {
  if (!html) return '';

  const tags = html.match(/<input\b[^>]*>/gi) || [];
  for (const tag of tags) {
    const name = getAttr(tag, 'name');
    if (name && name.toLowerCase() === 'csrf') {
      const value = getAttr(tag, 'value');
      if (value !== undefined) return value;
    }
  }

  const fallback = html.match(/<input\b[^>]*\bname\s*=\s*(?:"csrf"|'csrf'|\bcsrf\b)[^>]*>/i);
  if (fallback) {
    const value = getAttr(fallback[0], 'value');
    if (value !== undefined) return value;
  }

  return '';
}

function getAttr(tag, attr) {
  const re = new RegExp(
    '\\b' + attr + '\\s*=\\s*(?:"([^"]*)"|\'([^\']*)\'|([^\\s>]+))',
    'i'
  );
  const m = tag.match(re);
  if (!m) return undefined;
  return m[1] !== undefined ? m[1] : m[2] !== undefined ? m[2] : m[3];
}
